steps.script:
# burns reads PNG, JPEG, and WebP; other stills go through a PNG.
case "$GB_IN" in
  *.[pP][nN][gG] | *.[jJ][pP][gG] | *.[jJ][pP][eE][gG] | *.[wW][eE][bB][pP]) img=$GB_IN ;;
  *) img=$GB_WORK/still.png
     ffmpeg -hide_banner -nostdin -loglevel error -i "$GB_IN" -frames:v 1 -y "$img" ;;
esac
# The whole burns project, from the params (burns rejects missing or unknown fields);
# the render flags below replace its size, rate, and length.
jq '{
  version: 1,
  output: {width: 1920, height: 1080},
  timeline: {fps: {num: 30, den: 1}, frames: 30},
  seed: .seed,
  camera: (
    if .motion == "still" then
      {type: "still", view: {zoom: .view_zoom, x: .view_x, y: .view_y, roll_degrees: .view_roll}}
    elif .motion == "transform" then
      {type: "transform",
       start: {zoom: .start_zoom, x: .start_x, y: .start_y, roll_degrees: .start_roll},
       end: {zoom: .end_zoom, x: .end_x, y: .end_y, roll_degrees: .end_roll},
       easing: .easing}
    elif .motion == "tilt" then {type: "tilt", amount: .tilt_amount, easing: .easing}
    elif .motion == "breathing" then
      {type: "breathing", base_zoom: .breath_zoom, amplitude: .breath_swing, cycles: .breath_cycles}
    elif .motion == "figure-eight" then
      {type: "figure-eight", zoom: .eight_zoom, amplitude: [.eight_x, .eight_y], cycles: .eight_cycles}
    else
      {type: "depth", motion: .depth_motion, height: .depth_height, steady: .depth_steady,
       focus: .depth_focus, zoom: .depth_zoom, amount: .depth_amount, cycles: .depth_cycles}
    end),
  depth: {invert: .depth_invert},
  shake: {enabled: .shake, profile: .shake_profile, amount: .shake_amount, speed: .shake_speed},
  warp: (
    if .warp_type == "ripple" then
      {type: "ripple", enabled: .warp, amplitude: .warp_amplitude, wavelength: .warp_wavelength,
       center: [.warp_center_x, .warp_center_y], cycles: .warp_cycles}
    else
      {type: "heat-shimmer", enabled: .warp, amplitude: .warp_amplitude, spatial_scale: .warp_scale,
       cycles: .warp_cycles}
    end)
}' "$GB_PARAMS" > "$GB_WORK/project.json"
depth=()
if [ "$GB_P_MOTION" = depth ]; then
  depth=(--auto-depth)
  [ -z "$GB_P_DEPTH" ] || depth=(--depth "$GB_P_DEPTH")
fi
burns render -i "$img" -o "$GB_WORK/motion.mp4" --config "$GB_WORK/project.json" \
  --fps "$GB_FPS" --duration "$GB_DURATION" --width "$GB_WIDTH" --height "$GB_HEIGHT" --crf 0 "${depth[@]}"
# Layers are MKV; lossless H.264 is remuxed, not re-encoded.
ffmpeg -hide_banner -nostdin -loglevel error -i "$GB_WORK/motion.mp4" -map 0:v:0 -c copy \
  -fflags +bitexact -map_metadata -1 -map_chapters -1 -y "$GB_OUT"
